from itertools import combinations
import random

n = 9
required = [(4,7),(0,7)]

def is_triangle_free(adj):
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return False
    return True

def is_maximal(adj):
    # for every non-edge, adding it must create a triangle
    for u,v in combinations(range(n),2):
        if v in adj[u]:
            continue
        # check common neighbor
        if not (adj[u] & adj[v]):
            return False
    return True

random.seed(0)
for trial in range(10000):
    adj = [set() for _ in range(n)]
    for u,v in required:
        adj[u].add(v); adj[v].add(u)
    edges_order = list(combinations(range(n),2))
    random.shuffle(edges_order)
    for u,v in edges_order:
        if v in adj[u]: continue
        if adj[u] & adj[v]: continue
        adj[u].add(v); adj[v].add(u)
    if is_triangle_free(adj) and is_maximal(adj):
        edges = []
        for u in range(n):
            for v in adj[u]:
                if v>u: edges.append((u,v))
        # check required
        if all((u,v) in edges for u,v in required):
            print(edges)
